update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p106","body":"یہ رات بھر جاگنا یہ دن بھر سونا کیا ہے؟\nیہ خشک آنکھوں میں آنسووں کا ہونا کیا ہے؟\n\nکیا ہے یہ ہجر کا ہونا جاناں\nیہ لفظوں کا توڑنا جوڑنا کیا ہے؟\n\nایسی بھی بات نہیں کہ ہم بھول گئے\nلیکن یہ پل پل کا رونا دھونا کیا ہے؟\n\nتم اس طرح سے بدلے ہو کہ ہم سوچتے رہ گئے\nیہ موسموں کا تبدیل ہونا کیا ہے؟\n\nتم جو بات ادھوری چھوڑ کے چلے جاتے ہو\nکچھ کہنا ہے، تو کھل کے کہو ناں، کیا یے؟\n\nاس کے تغافل سے بارہاں یہ محسوس ہوتا ہے\nاس کے لیے ایک دوست کا کھونا کیا ہے؟"},{"slug":"tum-p107","body":"میرے لفظوں میں اب پہلے سا جادو نہیں ہے\nشاید یہ اس سبب ہے کہ تو روبرو نہیں ہے\n\nکِھلے کِھلے سے ہیں اب بھی کئی گُل انجمن میں\nپر اب کسی کو توڑنے کی آرزو نہیں ہے\n\nدل اب بھی دھڑکتا ہے ، کسی کے نام لینے پر\nپر وہ تجھ سا نام لینے کے ہوبہو نہیں ہے\n\nمت رکھ میری ہتھیلی پہ اپنا موم سا دل\nمیرا خود پہ بھی ذرا قابو نہیں ہے\n\nوہ پہلے سی ہنسی تو نہیں معلوم\nاحمد ؔ پر وہ پہلے سا گیسو نہیں ہے"},{"slug":"tum-p108","body":"دل شکن اور شب اندھیرا\nتم بن کیا ہوگا میرا\n\nکہتی ہے خود سے کھٹکتی کھڑکیاں\nمنظر اب کون دیکھے گا تیرا\n\nرات گئے سنسناتے آنگن میں\nسجتا ہے یادوں کا ڈیرا\n\nبن جانے ہی برسنے لگتے ہو\nشاہین کا چٹانوں پہ ہے بسیرا\n\nاحمد ؔ رات ہوئی کہ گھبرانے لگے\nآگے پھر آئے گا شام سویرا"},{"slug":"tum-p109","body":"کیا کہیں ، سنتی رہیں\nیہ آنکھیں ، تکتی رہیں\n\nیہ باتیں ، کبھی نہ رکیں\nیہ سانسیں ، چلتی رہیں\n\nتیری یادیں ، ستائیں مجھے\nیہ دوریاں،  بڑھتی رہیں\n\nخاموشیاں سنائی دیں\nمدہوشیاں سنتی رہیں\n\nراستے بدلتے رہیں\nمنزلیں ملتی رہیں\n\nیہ دنیا کسی کی کہاں\nسب کشتیاں جلتی رہیں\n\nمحبت وہی ساکن رہے\nفقط چاہتیں بدلتی رہیں"},{"slug":"tum-p110","body":"ایک خواہش پوری ہو کر بھی ادھوری رہی\nمنزل ایک تھی مگر تا دم آخر دوری رہی\n\nتیرے ملنے کی جستجو نے ہاتھ جوڑ لیے\nتیرے آنے کی آرزو مگر باقی رہی\n\nچاند کچھ دنوں کے لیے غائب ہوا\nدہر پہ تب بھی ستاروں کی روشنی رہی\n\nبہار آئی کہ ہر طرف پھول کھلنے لگے\nمگر وہ شاخ جو خزاں میں ٹوٹی رہی\n\nغم اور بھی تھے اک تیرے غم کے سوا\nپر صرف تیری یاد ہی وجہ اداسی رہی\n\nمجھ میں اور بہت خصوصیات تھیں اگرچہ\nاحمد ؔ مگر مجھ میں ہمیشہ تیری کمی رہی"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
